 "content": "def transform(grid):
    """Complete missing horizontal mirror tiles for each color's demonstrated tile pair."""
    h, w = len(grid), len(grid[0])

    # Uniform, nonzero full-width/full-height lines are the tile separators.
    row_seps = [r for r, row in enumerate(grid)
                if row[0] != 0 and all(v == row[0] for v in row)]
    col_seps = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    r_edges = [-1] + row_seps + [h]
    c_edges = [-1] + col_seps + [w]
    row_tiles = [(r_edges[i] + 1, r_edges[i + 1]) for i in range(len(r_edges) - 1)]
    col_tiles = [(c_edges[i] + 1, c_edges[i + 1]) for i in range(len(c_edges) - 1)]

    # Find each color's established adjacent tile pair from a row where both
    # tiles contain horizontally reflected copies of that color's pattern.
    pair_colors = set()
    for r0, r1 in row_tiles:
        for j in range(len(col_tiles) - 1):
            c0, c1 = col_tiles[j]
            d0, d1 = col_tiles[j + 1]
            if r1 - r0 != r1 - r0 or c1 - c0 != d1 - d0:
                continue
            for color in range(1, 10):
                left = [[int(grid[r][c] == color) for c in range(c0, c1)] for r in range(r0, r1)]
                right = [[int(grid[r][c] == color) for c in range(d0, d1)] for r in range(r0, r1)]
                if any(any(row) for row in left) and any(any(row) for row in right):
                    if left == [row[::-1] for row in right]:
                        pair_colors.add((color, j))

    out = [row[:] for row in grid]
    for color, j in pair_colors:
        c0, c1 = col_tiles[j]
        d0, d1 = col_tiles[j + 1]
        if c1 - c0 != d1 - d0:
            continue
        for r0, r1 in row_tiles:
            left_has = any(grid[r][c] == color for r in range(r0, r1) for c in range(c0, c1))
            right_has = any(grid[r][c] == color for r in range(r0, r1) for c in range(d0, d1))
            if left_has == right_has:
                continue
            if left_has:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        if grid[r][c] == color:
                            target_c = d0 + (c1 - 1 - c)
                            if out[r][target_c] == 0:
                                out[r][target_c] = color
            else:
                for r in range(r0, r1):
                    for c in range(d0, d1):
                        if grid[r][c] == color:
                            target_c = c0 + (d1 - 1 - c)
                            if out[r][target_c] == 0:
                                out[r][target_c] = color
    return out
